INSERT INTO public.tasks(title,topic,brief,words,tier,payout,payout_min,payout_max,is_demo,status)
SELECT x.title,x.topic,x.brief,x.words,x.tier,x.payout,x.payout_min,x.payout_max,x.is_demo,x.status
FROM seed x
WHERE NOT EXISTS (SELECT 1 FROM public.tasks t WHERE t.title=x.title AND t.is_demo=true);
